return ['domain'=>'zinn-chat','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-chat','pot-creation-date'=>'2026-09-09T22:42:23+00:00','po-revision-date'=>'2026-09-09T22:42:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Chat'=>'Zinn® Chat','https://zinndigital.com/wordpress-plugins/zinn-chat'=>'https://zinndigital.com/wordpress-plugins/zinn-chat','A fast, privacy-respecting live chat for your website. Answers visitors with AI when you are busy, hands them to you when they need a person, and emails you anything you miss. Under 5 KB on the page and no requests at all until somebody opens it.'=>'Brz i privatnost usmjeren live chat za vašu web-lokaciju. Odgovara posjetiteljima pomoću umjetne inteligencije kada ste zauzeti, preusmjerava ih na vas kada trebaju živu osobu i šalje vam e-poštu o svemu što ste propustili. Manje od 5 KB na stranici i bez ikakvih zahtjeva dok ga netko ne otvori.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Settings'=>'Postavke','That does not look like a Zinn® Chat key. Copy it from the Live chat page of your Zinn Digital® dashboard — it starts with zc_.'=>'To ne izgleda kao ključ za Zinn® Chat. Kopirajte ga sa stranice Live chat na nadzornoj ploči Zinn Digital® – počinje s zc_.','Add your chat key before switching the chat on — without it there is nothing for the widget to connect to.'=>'Dodajte svoj ključ za chat prije nego što uključite chat — bez njega widget se nema s čime povezati.','Live chat for this site. Visitors get an answer straight away, you get anything you miss by email, and the whole thing is under 5 KB on the page.'=>'Razgovor uživo za ovu stranicu. Posjetitelji odmah dobivaju odgovor, sve što propustite stiže vam e-poštom, a cijela stvar zauzima manje od 5 KB na stranici.','The chat is live on this site.'=>'Razgovor je aktivan na ovoj stranici.','The chat is switched off. Nothing is loaded on your site.'=>'Chat je isključen. Ništa nije učitano na vašoj stranici.','Chat key'=>'Ključ za chat','Copy this from the Live chat page of your %s.'=>'Kopirajte ovo sa stranice uživo chata vašeg %s.','Zinn Digital® dashboard'=>'Zinn Digital® upravljačka ploča','Show the chat'=>'Prikaži chat','Show the chat window to visitors of this site'=>'Prikaži prozor za chat posjetiteljima ove stranice','Until you tick this, the plugin adds nothing at all to your pages — no script, no cookie, no requests.'=>'Dok to ne označite, dodatak ne dodaje apsolutno ništa na vaše stranice – ni skriptu, ni kolačić, ni zahtjeve.','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnički vodiči','Read the %s user guide'=>'Pročitajte korisnički priručnik za %s','Hide this'=>'Sakrij ovo','Zinn® hosting for WordPress'=>'Zinn® hosting za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, dnevne sigurnosne kopije, besplatna migracija i upravljačka ploča prilagođena osobama koje upravljaju s više web-mjesta.','The Zinn® marketplace'=>'Zinn® tržnica','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajite postojeće web-lokacije, domene i postavljanja poveznica, uz sigurno čuvanje novca sve dok obje strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — zaposlite ljude kojima je to životni poziv','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globalno tržište slobodnih zanimanja: pregledajte više od 10.000 gotovih usluga pisaca, dizajnera, programera i SEO stručnjaka ili objavite projekt i dopustite im da daju ponude.','See the Zinn Digital® release notes.'=>'Pogledajte bilješke o izdanju Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'Preuzeto ažuriranje nije prošlo provjeru cjelovitosti i nije instalirano.']];